package com.stocksense.inventory.transfer; import com.stocksense.inventory.stock.StockService; import lombok.RequiredArgsConstructor; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.math.BigDecimal; import java.util.Map; @RestController @RequestMapping("/api/transfers") @RequiredArgsConstructor public class TransferController { private final StockService stock; record Req(Long productId,Long sourceLocationId,Long destinationLocationId,BigDecimal quantity){} @PostMapping("/validate") public Map<String,Object> validate(@RequestBody Req r,Authentication a){stock.transfer(r.productId(),r.sourceLocationId(),r.destinationLocationId(),r.quantity(),a.getName());return Map.of("status","DONE","message","Transfer completed atomically");} }
